-- Administrative migration-history backup
-- Database: ikontrol_new; table: ikontrol_migrations; rows: 96
SET NAMES utf8mb4;
START TRANSACTION;
DROP TABLE IF EXISTS `ikontrol_migrations`;
CREATE TABLE `ikontrol_migrations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `version` varchar(255) NOT NULL,
  `class` varchar(255) NOT NULL,
  `group` varchar(255) NOT NULL,
  `namespace` varchar(255) NOT NULL,
  `time` int(11) NOT NULL,
  `batch` int(11) unsigned NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=97 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;
COMMIT;
